  ('eric-wilson', 'Listed on the printed ballot as Republican. Candidate for Georgia House of Representatives, District 145, in the November 3, 2026 election. Source: Macon-Bibb Board of Elections composite sample ballot, October 15 revision. Verified October 21, 2026.', 'Eric Wilson is a paramedic, ambulance-service business owner, and former Forsyth mayor campaigning on taxes, insurance costs, and public safety.'),
  ('tangie-herring', 'Listed on the printed ballot as Democrat; marked incumbent by the county. Candidate for Georgia House of Representatives, District 145, in the November 3, 2026 election. Source: Macon-Bibb Board of Elections composite sample ballot, October 15 revision. Verified October 21, 2026.', 'Tangie Herring is a classroom teacher, small business owner, and state representative advocating affordable housing and stronger neighborhoods.'),
  ('randy-peters', 'Listed on the printed ballot as Republican. Candidate for Georgia House of Representatives, District 149, in the November 3, 2026 election. Source: Macon-Bibb Board of Elections composite sample ballot, October 15 revision. Verified October 21, 2026.', 'Randy Peters is a Milledgeville laboratory-business founder campaigning for the Georgia House on jobs, rural health care, and education.'),
  ('floyd-griffin', 'Listed on the printed ballot as Democrat; marked incumbent by the county. Candidate for Georgia House of Representatives, District 149, in the November 3, 2026 election. Source: Macon-Bibb Board of Elections composite sample ballot, October 15 revision. Verified October 21, 2026.', 'Floyd Griffin is a former state senator and Milledgeville mayor whose campaign emphasizes reproductive rights, health care, and veterans.'),
  ('lindsay-d-holliday', 'Listed on the printed ballot as nonpartisan; marked incumbent by the county. Candidate for Bibb County Soil and Water Conservation District Supervisor, Bibb County (countywide), in the November 3, 2026 election. Source: Macon-Bibb Board of Elections composite sample ballot, October 15 revision. Verified October 21, 2026.', 'Lindsay D. Holliday serves as a Bibb County soil and water conservation district supervisor and is running for re-election.')
) as verified(slug, previous_description, description)
where p.slug = verified.slug
  and (p.description is null or p.description = verified.previous_description)
  and exists (
    select 1 from public.contest_candidates cc
    join public.contests c on c.id = cc.contest_id
    join public.elections e on e.id = c.election_id
    where cc.person_id = p.id
      and e.slug = '2026-11-03-general-election'
      and e.election_date = date '2026-11-03'
  );
